CREATE TABLE IF NOT EXISTS bookings ( id INTEGER PRIMARY KEY AUTOINCREMENT, reference TEXT NOT NULL UNIQUE, name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT NOT NULL, pickup TEXT NOT NULL, destination TEXT NOT NULL, pickup_date TEXT NOT NULL, pickup_time TEXT NOT NULL, passengers TEXT NOT NULL, trip_type TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'confirmed', 'declined', 'contacted', 'completed', 'cancelled')), created_at TEXT NOT NULL, updated_at TEXT, tip_amount REAL CHECK (tip_amount IS NULL OR tip_amount >= 0), tip_recorded_at TEXT ); CREATE INDEX IF NOT EXISTS idx_bookings_created_at ON bookings(created_at); CREATE INDEX IF NOT EXISTS idx_bookings_pickup_date ON bookings(pickup_date); CREATE INDEX IF NOT EXISTS idx_bookings_status ON bookings(status); CREATE TABLE IF NOT EXISTS owner_sessions ( token_hash TEXT PRIMARY KEY, expires_at TEXT NOT NULL, created_at TEXT NOT NULL ); CREATE INDEX IF NOT EXISTS idx_owner_sessions_expiry ON owner_sessions(expires_at); CREATE TABLE IF NOT EXISTS trip_tips ( id INTEGER PRIMARY KEY AUTOINCREMENT, reference TEXT NOT NULL UNIQUE, booking_reference TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK (amount_cents > 0), currency TEXT NOT NULL DEFAULT 'USD', status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'paid', 'cancelled')), payment_provider TEXT, payment_reference TEXT, created_at TEXT NOT NULL, paid_at TEXT, FOREIGN KEY (booking_reference) REFERENCES bookings(reference) ); CREATE INDEX IF NOT EXISTS idx_trip_tips_booking_reference ON trip_tips(booking_reference); CREATE INDEX IF NOT EXISTS idx_trip_tips_status ON trip_tips(status); CREATE TABLE IF NOT EXISTS pricing_settings ( id INTEGER PRIMARY KEY CHECK (id = 1), minimum_fare_cents INTEGER NOT NULL DEFAULT 5000 CHECK (minimum_fare_cents >= 0), price_per_mile_cents INTEGER NOT NULL DEFAULT 250 CHECK (price_per_mile_cents >= 0), weekend_adjustment_cents INTEGER NOT NULL DEFAULT 1000 CHECK (weekend_adjustment_cents >= 0), late_night_adjustment_cents INTEGER NOT NULL DEFAULT 1000 CHECK (late_night_adjustment_cents >= 0), quote_expiration_hours INTEGER NOT NULL DEFAULT 24 CHECK (quote_expiration_hours BETWEEN 1 AND 168), updated_at TEXT NOT NULL ); INSERT OR IGNORE INTO pricing_settings ( id, minimum_fare_cents, price_per_mile_cents, weekend_adjustment_cents, late_night_adjustment_cents, quote_expiration_hours, updated_at ) VALUES ( 1, 5000, 250, 1000, 1000, 24, '2026-10-12T00:00:00.000Z' ); CREATE TABLE IF NOT EXISTS ride_quotes ( id INTEGER PRIMARY KEY AUTOINCREMENT, reference TEXT NOT NULL UNIQUE, booking_reference TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ( 'draft', 'issued', 'accepted', 'declined', 'expired', 'cancelled', 'superseded' )), mileage REAL NOT NULL DEFAULT 0 CHECK (mileage >= 0 AND mileage <= 10000), base_fare_cents INTEGER NOT NULL DEFAULT 0 CHECK (base_fare_cents >= 0), mileage_fare_cents INTEGER NOT NULL DEFAULT 0 CHECK (mileage_fare_cents >= 0), weekend_adjustment_cents INTEGER NOT NULL DEFAULT 0 CHECK (weekend_adjustment_cents >= 0), late_night_adjustment_cents INTEGER NOT NULL DEFAULT 0 CHECK (late_night_adjustment_cents >= 0), manual_adjustment_cents INTEGER NOT NULL DEFAULT 0, final_fare_cents INTEGER, owner_notes TEXT NOT NULL DEFAULT '', customer_token_hash TEXT UNIQUE, created_at TEXT NOT NULL, issued_at TEXT, expires_at TEXT, responded_at TEXT, updated_at TEXT NOT NULL, FOREIGN KEY (booking_reference) REFERENCES bookings(reference), CHECK (final_fare_cents IS NULL OR final_fare_cents >= 0) ); CREATE INDEX IF NOT EXISTS idx_ride_quotes_booking ON ride_quotes(booking_reference); CREATE INDEX IF NOT EXISTS idx_ride_quotes_status_expiry ON ride_quotes(status, expires_at); ALTER TABLE bookings ADD COLUMN additional_stops TEXT NOT NULL DEFAULT '[]'; CREATE TABLE IF NOT EXISTS mileage_usage ( day TEXT PRIMARY KEY, request_count INTEGER NOT NULL DEFAULT 0 CHECK (request_count >= 0) ); CREATE TABLE IF NOT EXISTS review_invitations ( id INTEGER PRIMARY KEY AUTOINCREMENT, booking_reference TEXT NOT NULL UNIQUE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, used_at TEXT ); CREATE TABLE IF NOT EXISTS customer_reviews ( id INTEGER PRIMARY KEY AUTOINCREMENT, booking_reference TEXT NOT NULL UNIQUE, customer_name TEXT NOT NULL, rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5), feedback TEXT NOT NULL, permission_to_publish INTEGER NOT NULL DEFAULT 0 CHECK (permission_to_publish IN (0, 1)), moderation_status TEXT NOT NULL DEFAULT 'pending' CHECK ( moderation_status IN ( 'pending', 'published', 'hidden' ) ), owner_response TEXT, owner_response_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (booking_reference) REFERENCES bookings(reference) ); CREATE INDEX IF NOT EXISTS idx_customer_reviews_public ON customer_reviews ( moderation_status, permission_to_publish, created_at ); CREATE INDEX IF NOT EXISTS idx_review_invitations_token ON review_invitations (token_hash); CREATE TABLE IF NOT EXISTS square_payments ( id INTEGER PRIMARY KEY AUTOINCREMENT, quote_reference TEXT NOT NULL, booking_reference TEXT NOT NULL, payment_type TEXT NOT NULL CHECK (payment_type IN ('deposit', 'balance')), amount_cents INTEGER NOT NULL CHECK (amount_cents > 0), currency TEXT NOT NULL DEFAULT 'USD' CHECK (currency = 'USD'), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ( 'pending', 'paid', 'failed', 'cancelled', 'refunded' )), square_environment TEXT NOT NULL DEFAULT 'sandbox' CHECK (square_environment IN ('sandbox', 'production')), square_order_id TEXT, square_payment_link_id TEXT, square_payment_id TEXT UNIQUE, checkout_url TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, paid_at TEXT, FOREIGN KEY (quote_reference) REFERENCES ride_quotes(reference), FOREIGN KEY (booking_reference) REFERENCES bookings(reference), UNIQUE (quote_reference, payment_type) ); CREATE INDEX IF NOT EXISTS idx_square_payments_booking ON square_payments(booking_reference); CREATE INDEX IF NOT EXISTS idx_square_payments_status ON square_payments(status); ALTER TABLE square_payments ADD COLUMN checkout_key TEXT; ALTER TABLE square_payments ADD COLUMN checkout_request TEXT; CREATE TABLE IF NOT EXISTS square_balance_invoices ( payment_id INTEGER PRIMARY KEY REFERENCES square_payments(id), square_customer_id TEXT, square_invoice_id TEXT UNIQUE, invoice_status TEXT NOT NULL DEFAULT 'DRAFT', preferred_method TEXT NOT NULL DEFAULT 'online' CHECK (preferred_method IN ('online', 'reader')), verified_payment_ids TEXT NOT NULL DEFAULT '[]', verified_amount_cents INTEGER NOT NULL DEFAULT 0 CHECK (verified_amount_cents >= 0), review_required INTEGER NOT NULL DEFAULT 0 CHECK (review_required IN (0, 1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
